INSERT INTO val_regla VALUES ('OPERACION_TRX_CALIFICACION_BC_INTENTO_ORDINARIO_Y_RECUPERACION','OPERACION','trx_calificacion','BLOQUEO','La ordinaria es el intento 1 y no referencia una ordinaria de origen; las recuperaciones son intentos 2 o superiores y sí la referencian. Las correcciones mantienen el intento y aumentan la versión.','SELECT s.* FROM trx_calificacion s WHERE NOT ((tipo_intento = ''ORDINARIA'' AND numero_intento = 1 AND id_calificacion_ordinaria IS NULL) OR (tipo_intento = ''RECUPERACION'' AND numero_intento >= 2 AND id_calificacion_ordinaria IS NOT NULL))');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CALIFICACION_BC_RESULTADO_REAL_EXCLUYENTE','OPERACION','trx_calificacion','BLOQUEO','Cada fila guarda exactamente un resultado real numérico o cualitativo; las notas pendientes no generan filas.','SELECT s.* FROM trx_calificacion s WHERE NOT ((nota IS NOT NULL AND resultado_cualitativo IS NULL) OR (nota IS NULL AND resultado_cualitativo IS NOT NULL))');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CALIFICACION_BC_VERSION_CON_ANTECEDENTE','OPERACION','trx_calificacion','BLOQUEO','La versión 1 no tiene sustituida; una corrección posterior referencia una versión anterior del mismo intento.','SELECT s.* FROM trx_calificacion s WHERE NOT ((version = 1 AND id_calificacion_sustituida IS NULL) OR (version > 1 AND id_calificacion_sustituida IS NOT NULL))');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CALIFICACION_BC_FECHAS_CALIFICACION_ORDENADAS','OPERACION','trx_calificacion','BLOQUEO','La validación y la anulación no preceden al registro; una anulación requiere motivo.','SELECT s.* FROM trx_calificacion s WHERE NOT ((fecha_validacion IS NULL OR fecha_validacion >= fecha_registro) AND (fecha_anulacion IS NULL OR (fecha_anulacion >= fecha_registro AND motivo_anulacion IS NOT NULL)))');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CALIFICACION_PK','OPERACION','trx_calificacion','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_calificacion) AS duplicados FROM trx_calificacion s) q WHERE q.duplicados>1 AND (id_calificacion IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CALIFICACION_UK_inscripcion_ponderacion_periodo_tipo_intento_numero_intento_version','OPERACION','trx_calificacion','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_inscripcion,id_ponderacion_periodo,tipo_intento,numero_intento,version) AS duplicados FROM trx_calificacion s) q WHERE q.duplicados>1 AND (id_inscripcion IS NOT NULL OR id_ponderacion_periodo IS NOT NULL OR tipo_intento IS NOT NULL OR numero_intento IS NOT NULL OR version IS NOT NULL)');
