INSERT INTO val_regla VALUES ('OPERACION_TRX_BECA_VIGENCIA_PK','OPERACION','trx_beca_vigencia','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_vigencia) AS duplicados FROM trx_beca_vigencia s) q WHERE q.duplicados>1 AND (id_vigencia IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_BECA_VIGENCIA_UK_beca_fecha_inicio','OPERACION','trx_beca_vigencia','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_beca,fecha_inicio) AS duplicados FROM trx_beca_vigencia s) q WHERE q.duplicados>1 AND (id_beca IS NOT NULL OR fecha_inicio IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_BECA_VIGENCIA_FK_beca','OPERACION','trx_beca_vigencia','BLOQUEO','La referencia de origen debe existir.','SELECT s.* FROM trx_beca_vigencia s WHERE s.id_beca IS NOT NULL AND NOT EXISTS (SELECT 1 FROM trx_beca p WHERE p.id_beca=s.id_beca)');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_id_ejecucion','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE id_ejecucion IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_fuente','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE fuente IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_inicio','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE inicio IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_estado','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE estado IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_CK_estado','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Dominio y rango acordados.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE NOT (estado IN (''EN_PROCESO'',''COMPLETADA'',''ERROR''))');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_total_leidos','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE total_leidos IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_insertados','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE insertados IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_actualizados','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE actualizados IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_NN_rechazados','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM auditoria_etl_evaluaciones s WHERE rechazados IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_ETL_EVALUACIONES_PK','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_ejecucion) AS duplicados FROM auditoria_etl_evaluaciones s) q WHERE q.duplicados>1 AND (id_ejecucion IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_NN_id_error','OPERACION','errores_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM errores_etl_evaluaciones s WHERE id_error IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_NN_id_ejecucion','OPERACION','errores_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM errores_etl_evaluaciones s WHERE id_ejecucion IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_NN_entidad','OPERACION','errores_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM errores_etl_evaluaciones s WHERE entidad IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_NN_tipo_error','OPERACION','errores_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM errores_etl_evaluaciones s WHERE tipo_error IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_NN_detalle','OPERACION','errores_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM errores_etl_evaluaciones s WHERE detalle IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_NN_json_original','OPERACION','errores_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM errores_etl_evaluaciones s WHERE json_original IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_CK_json_original','OPERACION','errores_etl_evaluaciones','BLOQUEO','Dominio y rango acordados.','SELECT s.* FROM errores_etl_evaluaciones s WHERE NOT (json_original IS JSON STRICT)');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_NN_fecha_registro','OPERACION','errores_etl_evaluaciones','BLOQUEO','Campo obligatorio.','SELECT s.* FROM errores_etl_evaluaciones s WHERE fecha_registro IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_PK','OPERACION','errores_etl_evaluaciones','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_error) AS duplicados FROM errores_etl_evaluaciones s) q WHERE q.duplicados>1 AND (id_error IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_ERRORES_ETL_EVALUACIONES_FK_ejecucion','OPERACION','errores_etl_evaluaciones','BLOQUEO','La referencia de origen debe existir.','SELECT s.* FROM errores_etl_evaluaciones s WHERE s.id_ejecucion IS NOT NULL AND NOT EXISTS (SELECT 1 FROM auditoria_etl_evaluaciones p WHERE p.id_ejecucion=s.id_ejecucion)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_id_control','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE id_control IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_id_curso','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE id_curso IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_id_periodo','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE id_periodo IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_dominio','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE dominio IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_CK_dominio','OPERACION','trx_control_carga','BLOQUEO','Dominio y rango acordados.','SELECT s.* FROM trx_control_carga s WHERE NOT (dominio IN (''MATRICULA'',''NOTAS'',''ASISTENCIA'',''BECAS''))');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_fecha_corte','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE fecha_corte IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_CK_fecha_corte','OPERACION','trx_control_carga','BLOQUEO','Dominio y rango acordados.','SELECT s.* FROM trx_control_carga s WHERE NOT (fecha_corte = TRUNC(fecha_corte))');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_estado','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE estado IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_CK_estado','OPERACION','trx_control_carga','BLOQUEO','Dominio y rango acordados.','SELECT s.* FROM trx_control_carga s WHERE NOT (estado IN (''COMPLETA'',''PARCIAL'',''NO_APLICA''))');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_registros_declarados','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE registros_declarados IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_CK_registros_declarados','OPERACION','trx_control_carga','BLOQUEO','Dominio y rango acordados.','SELECT s.* FROM trx_control_carga s WHERE NOT (registros_declarados >= 0)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_fecha_recepcion','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE fecha_recepcion IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_NN_id_ejecucion','OPERACION','trx_control_carga','BLOQUEO','Campo obligatorio.','SELECT s.* FROM trx_control_carga s WHERE id_ejecucion IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_PK','OPERACION','trx_control_carga','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_control) AS duplicados FROM trx_control_carga s) q WHERE q.duplicados>1 AND (id_control IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_UK_curso_periodo_dominio_fecha_corte','OPERACION','trx_control_carga','BLOQUEO','La clave de origen no puede repetirse.','SELECT q.* FROM (SELECT s.*,COUNT(*) OVER (PARTITION BY id_curso,id_periodo,dominio,fecha_corte) AS duplicados FROM trx_control_carga s) q WHERE q.duplicados>1 AND (id_curso IS NOT NULL OR id_periodo IS NOT NULL OR dominio IS NOT NULL OR fecha_corte IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_FK_curso','OPERACION','trx_control_carga','BLOQUEO','La referencia de origen debe existir.','SELECT s.* FROM trx_control_carga s WHERE s.id_curso IS NOT NULL AND NOT EXISTS (SELECT 1 FROM est_curso p WHERE p.id_curso=s.id_curso)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_FK_periodo','OPERACION','trx_control_carga','BLOQUEO','La referencia de origen debe existir.','SELECT s.* FROM trx_control_carga s WHERE s.id_periodo IS NOT NULL AND NOT EXISTS (SELECT 1 FROM est_periodo_academico p WHERE p.id_periodo=s.id_periodo)');
INSERT INTO val_regla VALUES ('OPERACION_TRX_CONTROL_CARGA_FK_ejecucion','OPERACION','trx_control_carga','BLOQUEO','La referencia de origen debe existir.','SELECT s.* FROM trx_control_carga s WHERE s.id_ejecucion IS NOT NULL AND NOT EXISTS (SELECT 1 FROM auditoria_etl_evaluaciones p WHERE p.id_ejecucion=s.id_ejecucion)');
INSERT INTO val_regla VALUES ('OPERACION_PERIODO_CICLO','OPERACION','est_periodo_academico','BLOQUEO','Períodos configurables positivos, contenidos en su ciclo, sin duración fija.','SELECT p.* FROM est_periodo_academico p JOIN est_ciclo c ON c.id_ciclo=p.id_ciclo WHERE (p.numero<1 OR p.numero<>TRUNC(p.numero)) OR p.fecha_inicio<c.fecha_inicio OR p.fecha_fin>c.fecha_fin OR p.fecha_fin<p.fecha_inicio');
INSERT INTO val_regla VALUES ('OPERACION_PERIODOS_SOLAPADOS','OPERACION','est_periodo_academico','BLOQUEO','No solapar períodos del mismo ciclo.','SELECT p.* FROM est_periodo_academico p WHERE EXISTS (SELECT 1 FROM est_periodo_academico q WHERE q.id_ciclo=p.id_ciclo AND q.id_periodo<>p.id_periodo AND q.fecha_inicio<=p.fecha_fin AND p.fecha_inicio<=q.fecha_fin)');
INSERT INTO val_regla VALUES ('OPERACION_PERIODOS_CONSECUTIVOS','OPERACION','est_periodo_academico','AVISO','Períodos numerados 1..N sin huecos y en el orden de sus fechas; un hueco puede indicar un período no cargado.','SELECT p.* FROM est_periodo_academico p WHERE EXISTS (SELECT 1 FROM est_periodo_academico q WHERE q.id_ciclo=p.id_ciclo GROUP BY q.id_ciclo HAVING MAX(q.numero)<>COUNT(*)) OR EXISTS (SELECT 1 FROM est_periodo_academico q WHERE q.id_ciclo=p.id_ciclo AND q.id_periodo<>p.id_periodo AND ((q.numero<p.numero AND q.fecha_inicio>p.fecha_inicio) OR (q.numero>p.numero AND q.fecha_inicio<p.fecha_inicio)))');
INSERT INTO val_regla VALUES ('OPERACION_CICLO_ANIO_INICIO','OPERACION','est_ciclo','AVISO','El año de referencia es el año de inicio del ciclo, aunque cruce años calendario.','SELECT c.* FROM est_ciclo c WHERE c.anio<>EXTRACT(YEAR FROM c.fecha_inicio)');
INSERT INTO val_regla VALUES ('OPERACION_PLAN_CICLO','OPERACION','est_ponderacion_periodo','BLOQUEO','Curso y período deben pertenecer al mismo ciclo.','SELECT p.* FROM est_ponderacion_periodo p JOIN est_curso_asignatura a ON a.id_curso_asignatura=p.id_curso_asignatura JOIN est_curso c ON c.id_curso=a.id_curso JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo WHERE c.id_ciclo<>x.id_ciclo');
INSERT INTO val_regla VALUES ('OPERACION_PLAN_COMPLETO','OPERACION','est_ponderacion_periodo','BLOQUEO','Un plan publicado cubre todos los períodos configurados de su ciclo.','SELECT p.* FROM est_ponderacion_periodo p WHERE p.id_ponderacion_periodo IN (SELECT q.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_curso_asignatura,COUNT(*) OVER (PARTITION BY w.id_curso_asignatura) AS publicados FROM est_ponderacion_periodo w WHERE w.estado=''PUBLICADO'') q LEFT JOIN est_curso_asignatura a ON a.id_curso_asignatura=q.id_curso_asignatura LEFT JOIN est_curso c ON c.id_curso=a.id_curso LEFT JOIN (SELECT id_ciclo,COUNT(*) AS periodos FROM est_periodo_academico GROUP BY id_ciclo) v ON v.id_ciclo=c.id_ciclo WHERE q.publicados<>COALESCE(v.periodos,0))');
INSERT INTO val_regla VALUES ('OPERACION_OFERTA_CON_PLAN','OPERACION','est_curso_asignatura','PENDIENTE','Una oferta activa con matrícula no puede ocultar un plan anual ausente.','SELECT o.* FROM est_curso_asignatura o LEFT JOIN (SELECT id_curso_asignatura,COUNT(*) AS publicados FROM est_ponderacion_periodo WHERE estado=''PUBLICADO'' GROUP BY id_curso_asignatura) w ON w.id_curso_asignatura=o.id_curso_asignatura LEFT JOIN est_curso c ON c.id_curso=o.id_curso LEFT JOIN (SELECT id_ciclo,COUNT(*) AS periodos FROM est_periodo_academico GROUP BY id_ciclo) v ON v.id_ciclo=c.id_ciclo WHERE o.estado=''ACTIVA'' AND EXISTS (SELECT 1 FROM trx_inscripcion i WHERE i.id_curso=o.id_curso AND i.estado<>''ANULADA'') AND COALESCE(w.publicados,0)<>COALESCE(v.periodos,0)');
INSERT INTO val_regla VALUES ('OPERACION_PLAN_CON_PLAZO','OPERACION','est_ponderacion_periodo','PENDIENTE','Todo componente publicado tiene plazo ordinario del contexto correspondiente.','SELECT p.* FROM est_ponderacion_periodo p JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN est_curso c ON c.id_curso=o.id_curso WHERE p.estado=''PUBLICADO'' AND NOT EXISTS (SELECT 1 FROM est_plazo_registro_notas w WHERE w.id_institucion=c.id_institucion AND w.id_ciclo=c.id_ciclo AND w.id_grado=c.id_grado AND w.id_periodo=p.id_periodo AND w.tipo_intento=''ORDINARIA'')');
INSERT INTO val_regla VALUES ('OPERACION_PESOS_COMPARABLES','OPERACION','est_ponderacion_periodo','BLOQUEO','Mismo ciclo, grado y asignatura: igual vector normalizado.','SELECT p.* FROM est_ponderacion_periodo p WHERE p.id_ponderacion_periodo IN (SELECT x.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM est_ponderacion_periodo w JOIN est_curso_asignatura a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN est_curso c ON c.id_curso=a.id_curso WHERE w.estado=''PUBLICADO'') x JOIN (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM est_ponderacion_periodo w JOIN est_curso_asignatura a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN est_curso c ON c.id_curso=a.id_curso WHERE w.estado=''PUBLICADO'') y ON y.id_periodo=x.id_periodo AND y.id_ciclo=x.id_ciclo AND y.id_grado=x.id_grado AND y.id_asignatura=x.id_asignatura WHERE ABS(x.peso*y.total-y.peso*x.total)>0.00000001)');
INSERT INTO val_regla VALUES ('OPERACION_INSCRIPCION_CICLO','OPERACION','trx_inscripcion','BLOQUEO','Pertenencia dentro del ciclo, con intervalos inclusivos.','SELECT i.* FROM trx_inscripcion i JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE i.fecha_inicio<x.fecha_inicio OR i.fecha_inicio>x.fecha_fin OR (i.fecha_fin IS NOT NULL AND (i.fecha_fin<i.fecha_inicio OR i.fecha_fin>x.fecha_fin))');
INSERT INTO val_regla VALUES ('OPERACION_INSCRIPCIONES_SOLAPADAS','OPERACION','trx_inscripcion','BLOQUEO','No solapar matrículas ordinarias del mismo estudiante y ciclo.','SELECT i.* FROM trx_inscripcion i WHERE i.id_inscripcion IN (SELECT w.id_inscripcion FROM (SELECT v.*,LAG(v.max_fin) OVER (PARTITION BY v.id_estudiante,v.id_ciclo ORDER BY v.fecha_inicio,v.id_inscripcion) AS fin_previo FROM (SELECT t.id_inscripcion,t.id_estudiante,c.id_ciclo,t.fecha_inicio,COALESCE(t.fecha_fin,x.fecha_fin) AS fin,MAX(COALESCE(t.fecha_fin,x.fecha_fin)) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion ROWS UNBOUNDED PRECEDING) AS max_fin,LEAD(t.fecha_inicio) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion) AS inicio_siguiente FROM trx_inscripcion t JOIN est_curso c ON c.id_curso=t.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE t.estado<>''ANULADA'') v) w WHERE w.fin_previo>=w.fecha_inicio OR w.inicio_siguiente<=w.fin)');
INSERT INTO val_regla VALUES ('OPERACION_ASIGNACION_CICLO','OPERACION','trx_asignacion_docente','BLOQUEO','La responsabilidad ordinaria pertenece al ciclo de la oferta.','SELECT a.* FROM trx_asignacion_docente a JOIN est_curso_asignatura o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN est_curso c ON c.id_curso=o.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE a.fecha_inicio<x.fecha_inicio OR a.fecha_inicio>x.fecha_fin OR (a.fecha_fin IS NOT NULL AND (a.fecha_fin<a.fecha_inicio OR a.fecha_fin>x.fecha_fin))');
INSERT INTO val_regla VALUES ('OPERACION_ASIGNACIONES_SOLAPADAS','OPERACION','trx_asignacion_docente','BLOQUEO','Un responsable por oferta y fecha.','SELECT a.* FROM trx_asignacion_docente a JOIN est_curso_asignatura o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN est_curso c ON c.id_curso=o.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE a.estado<>''ANULADA'' AND EXISTS (SELECT 1 FROM trx_asignacion_docente b WHERE b.id_asignacion<>a.id_asignacion AND b.id_curso_asignatura=a.id_curso_asignatura AND b.estado<>''ANULADA'' AND a.fecha_inicio<=COALESCE(b.fecha_fin,x.fecha_fin) AND b.fecha_inicio<=COALESCE(a.fecha_fin,x.fecha_fin))');
INSERT INTO val_regla VALUES ('OPERACION_PLAZO_CICLO','OPERACION','est_plazo_registro_notas','BLOQUEO','El período del plazo pertenece a su ciclo.','SELECT w.* FROM est_plazo_registro_notas w JOIN est_periodo_academico p ON p.id_periodo=w.id_periodo WHERE w.id_ciclo<>p.id_ciclo');
INSERT INTO val_regla VALUES ('OPERACION_RECUPERACION_FECHAS','OPERACION','est_plazo_registro_notas','BLOQUEO','Recuperación exige intervalo ordenado; ordinaria lo deja vacío.','SELECT w.* FROM est_plazo_registro_notas w WHERE (w.tipo_intento=''ORDINARIA'' AND (w.fecha_inicio_recuperacion IS NOT NULL OR w.fecha_fin_recuperacion IS NOT NULL)) OR (w.tipo_intento=''RECUPERACION'' AND (w.fecha_inicio_recuperacion IS NULL OR w.fecha_fin_recuperacion IS NULL OR w.fecha_fin_recuperacion<w.fecha_inicio_recuperacion))');
INSERT INTO val_regla VALUES ('OPERACION_CALIFICACION_CONTEXTO','OPERACION','trx_calificacion','BLOQUEO','Calificación, inscripción y asignación corresponden a la misma oferta publicada.','SELECT n.* FROM trx_calificacion n JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN trx_asignacion_docente a ON a.id_asignacion=n.id_asignacion_docente WHERE i.id_curso<>o.id_curso OR a.id_curso_asignatura<>o.id_curso_asignatura OR i.estado=''ANULADA'' OR a.estado=''ANULADA'' OR p.estado<>''PUBLICADO''');
INSERT INTO val_regla VALUES ('OPERACION_TIPO_RESULTADO','OPERACION','trx_calificacion','BLOQUEO','Resultado numérico o cualitativo coherente con la oferta.','SELECT n.* FROM trx_calificacion n JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE (o.tipo_resultado=''NUMERICA'' AND (n.nota IS NULL OR n.resultado_cualitativo IS NOT NULL)) OR (o.tipo_resultado=''CUALITATIVA'' AND (n.nota IS NOT NULL OR n.resultado_cualitativo IS NULL))');
INSERT INTO val_regla VALUES ('OPERACION_ORDINARIA_VIGENCIA','OPERACION','trx_calificacion','BLOQUEO','La fecha académica ordinaria está en período, matrícula y responsabilidad.','SELECT n.* FROM trx_calificacion n JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo JOIN trx_asignacion_docente a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento=''ORDINARIA'' AND (n.fecha_evaluacion<x.fecha_inicio OR n.fecha_evaluacion>x.fecha_fin OR n.fecha_evaluacion<i.fecha_inicio OR n.fecha_evaluacion>COALESCE(i.fecha_fin,x.fecha_fin) OR n.fecha_evaluacion<a.fecha_inicio OR n.fecha_evaluacion>COALESCE(a.fecha_fin,x.fecha_fin))');
INSERT INTO val_regla VALUES ('OPERACION_RECUPERACION_RESPONSABLE','OPERACION','trx_calificacion','BLOQUEO','La recuperación queda a cargo de una asignación vigente en algún momento del período que recupera.','SELECT n.* FROM trx_calificacion n JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo JOIN trx_asignacion_docente a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento=''RECUPERACION'' AND (a.fecha_inicio>x.fecha_fin OR COALESCE(a.fecha_fin,x.fecha_fin)<x.fecha_inicio)');
INSERT INTO val_regla VALUES ('OPERACION_ORIGEN_RECUPERACION','OPERACION','trx_calificacion','BLOQUEO','La recuperación referencia su ordinaria y conserva inscripción y plan.','SELECT n.* FROM trx_calificacion n JOIN trx_calificacion b ON b.id_calificacion=n.id_calificacion_ordinaria WHERE n.tipo_intento=''RECUPERACION'' AND (b.tipo_intento<>''ORDINARIA'' OR b.numero_intento<>1 OR b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.fecha_evaluacion>n.fecha_evaluacion)');
INSERT INTO val_regla VALUES ('OPERACION_VERSION_ANTERIOR','OPERACION','trx_calificacion','BLOQUEO','La sustituida es la versión previa del mismo intento y contexto.','SELECT n.* FROM trx_calificacion n JOIN trx_calificacion b ON b.id_calificacion=n.id_calificacion_sustituida WHERE b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.tipo_intento<>n.tipo_intento OR b.numero_intento<>n.numero_intento OR b.version+1<>n.version OR b.fecha_registro>n.fecha_registro');
INSERT INTO val_regla VALUES ('OPERACION_CAPTURA_AUTORIZADA','OPERACION','trx_calificacion','BLOQUEO','Existe plazo compatible y la captura no precede apertura ni supera cierre real.','SELECT n.* FROM trx_calificacion n JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE n.id_calificacion NOT IN (SELECT m.id_calificacion FROM trx_calificacion m JOIN trx_inscripcion j ON j.id_inscripcion=m.id_inscripcion JOIN est_curso d ON d.id_curso=j.id_curso JOIN est_ponderacion_periodo q ON q.id_ponderacion_periodo=m.id_ponderacion_periodo JOIN est_plazo_registro_notas w ON w.id_institucion=d.id_institucion AND w.id_ciclo=d.id_ciclo AND w.id_grado=d.id_grado AND w.id_periodo=q.id_periodo AND w.tipo_intento=m.tipo_intento WHERE m.fecha_registro>=w.fecha_apertura_registro AND (w.fecha_cierre_registro IS NULL OR m.fecha_registro<=w.fecha_cierre_registro) AND (m.tipo_intento=''ORDINARIA'' OR m.fecha_evaluacion BETWEEN w.fecha_inicio_recuperacion AND w.fecha_fin_recuperacion))');
INSERT INTO val_regla VALUES ('OPERACION_REGISTRO_NO_ANTICIPADO','OPERACION','trx_calificacion','BLOQUEO','El registro no precede al hecho académico.','SELECT n.* FROM trx_calificacion n WHERE TRUNC(n.fecha_registro)<n.fecha_evaluacion');
INSERT INTO val_regla VALUES ('OPERACION_RESULTADO_CORRESPONDE','OPERACION','trx_resultado_periodo','BLOQUEO','La referencia seleccionada corresponde a estudiante, materia y período.','SELECT r.* FROM trx_resultado_periodo r JOIN trx_calificacion n ON n.id_calificacion=r.id_calificacion_seleccionada JOIN trx_inscripcion i ON i.id_inscripcion=n.id_inscripcion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE r.id_estudiante<>i.id_estudiante OR r.id_asignatura<>o.id_asignatura OR r.id_periodo<>p.id_periodo OR n.fecha_validacion IS NULL OR r.fecha_seleccion<n.fecha_validacion OR (r.fecha_cierre IS NOT NULL AND r.fecha_cierre<r.fecha_seleccion) OR (n.fecha_anulacion IS NOT NULL AND n.fecha_anulacion<=r.fecha_seleccion)');
INSERT INTO val_regla VALUES ('OPERACION_SELECCION_VERSION_VIGENTE','OPERACION','trx_resultado_periodo','BLOQUEO','Una selección usa la última versión validada de su intento en ese momento.','SELECT r.* FROM trx_resultado_periodo r JOIN trx_calificacion n ON n.id_calificacion=r.id_calificacion_seleccionada WHERE EXISTS (SELECT 1 FROM trx_calificacion v WHERE v.id_inscripcion=n.id_inscripcion AND v.id_ponderacion_periodo=n.id_ponderacion_periodo AND v.tipo_intento=n.tipo_intento AND v.numero_intento=n.numero_intento AND v.version>n.version AND v.fecha_validacion<=r.fecha_seleccion)');
INSERT INTO val_regla VALUES ('OPERACION_SELECCION_POLITICA','OPERACION','trx_resultado_periodo','BLOQUEO','La elección respeta mejor nota o última recuperación a fecha de selección, sin anticipar eventos futuros.','SELECT r.* FROM trx_resultado_periodo r WHERE r.id_resultado IN (SELECT x.id_resultado FROM trx_resultado_periodo x JOIN trx_calificacion n ON n.id_calificacion=x.id_calificacion_seleccionada JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN trx_calificacion m ON m.id_inscripcion=n.id_inscripcion AND m.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE m.fecha_validacion<=x.fecha_seleccion AND (m.fecha_anulacion IS NULL OR m.fecha_anulacion>x.fecha_seleccion) AND ((o.regla_recuperacion=''MEJOR_NOTA'' AND o.tipo_resultado=''NUMERICA'' AND m.nota>n.nota) OR (o.regla_recuperacion=''ULTIMA_RECUPERACION'' AND m.numero_intento>n.numero_intento)) AND NOT EXISTS (SELECT 1 FROM trx_calificacion v WHERE v.id_inscripcion=m.id_inscripcion AND v.id_ponderacion_periodo=m.id_ponderacion_periodo AND v.tipo_intento=m.tipo_intento AND v.numero_intento=m.numero_intento AND v.version>m.version AND v.fecha_validacion<=x.fecha_seleccion))');
INSERT INTO val_regla VALUES ('OPERACION_SESION_CONTEXTO','OPERACION','trx_sesion_clase','BLOQUEO','Sesión y responsabilidad compatibles; noche puede terminar al día siguiente.','SELECT s.* FROM trx_sesion_clase s JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN est_periodo_academico x ON x.id_periodo=p.id_periodo JOIN trx_asignacion_docente a ON a.id_asignacion=s.id_asignacion WHERE p.id_curso_asignatura<>a.id_curso_asignatura OR s.fecha_academica<x.fecha_inicio OR s.fecha_academica>x.fecha_fin OR s.fecha_academica<a.fecha_inicio OR s.fecha_academica>COALESCE(a.fecha_fin,x.fecha_fin) OR s.fin<=s.inicio OR TRUNC(s.inicio)<>s.fecha_academica OR a.estado=''ANULADA''');
INSERT INTO val_regla VALUES ('OPERACION_SESIONES_SIMULTANEAS','OPERACION','trx_sesion_clase','BLOQUEO','Un docente o grupo no recibe dos sesiones simultáneas.','SELECT s.* FROM trx_sesion_clase s WHERE s.id_sesion IN (SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,b.id_docente AS k,MAX(t.fin) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM trx_sesion_clase t JOIN trx_asignacion_docente b ON b.id_asignacion=t.id_asignacion WHERE t.estado<>''CANCELADA'') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin UNION SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,z.id_curso AS k,MAX(t.fin) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM trx_sesion_clase t JOIN est_ponderacion_periodo q ON q.id_ponderacion_periodo=t.id_ponderacion_periodo JOIN est_curso_asignatura z ON z.id_curso_asignatura=q.id_curso_asignatura WHERE t.estado<>''CANCELADA'') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin)');
INSERT INTO val_regla VALUES ('OPERACION_ASISTENCIA_CONTEXTO','OPERACION','trx_asistencia','BLOQUEO','La asistencia pertenece al curso e intervalo de la sesión.','SELECT a.* FROM trx_asistencia a JOIN trx_inscripcion i ON i.id_inscripcion=a.id_inscripcion JOIN trx_sesion_clase s ON s.id_sesion=a.id_sesion JOIN est_ponderacion_periodo p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN est_curso_asignatura o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE i.id_curso<>o.id_curso OR i.estado=''ANULADA'' OR s.estado<>''IMPARTIDA'' OR s.fecha_academica<i.fecha_inicio OR s.fecha_academica>COALESCE(i.fecha_fin,x.fecha_fin) OR a.fecha_registro<s.fin OR (a.estado IN (''AUSENTE'',''JUSTIFICADA'') AND a.hora_llegada IS NOT NULL)');
INSERT INTO val_regla VALUES ('OPERACION_BECA_HABILITADA','OPERACION','trx_beca','BLOQUEO','El beneficio respeta la habilitación histórica del centro.','SELECT b.* FROM trx_beca b JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_institucion_ciclo h ON h.id_institucion=c.id_institucion AND h.id_ciclo=c.id_ciclo WHERE h.permite_becas<>1 OR i.estado=''ANULADA''');
INSERT INTO val_regla VALUES ('OPERACION_BECA_VIGENCIA','OPERACION','trx_beca_vigencia','BLOQUEO','El intervalo efectivo queda dentro de matrícula y ciclo.','SELECT v.* FROM trx_beca_vigencia v JOIN trx_beca b ON b.id_beca=v.id_beca JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE v.fecha_inicio<i.fecha_inicio OR v.fecha_inicio>COALESCE(i.fecha_fin,x.fecha_fin) OR (v.fecha_fin IS NOT NULL AND (v.fecha_fin<v.fecha_inicio OR v.fecha_fin>COALESCE(i.fecha_fin,x.fecha_fin))) OR (v.fecha_fin IS NULL AND v.motivo_fin IS NOT NULL) OR (v.fecha_fin IS NOT NULL AND v.motivo_fin IS NULL)');
INSERT INTO val_regla VALUES ('OPERACION_BECA_SOLAPADA','OPERACION','trx_beca_vigencia','BLOQUEO','Una beca no tiene intervalos efectivos solapados.','SELECT v.* FROM trx_beca_vigencia v JOIN trx_beca b ON b.id_beca=v.id_beca JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE EXISTS (SELECT 1 FROM trx_beca_vigencia w WHERE w.id_beca=v.id_beca AND w.id_vigencia<>v.id_vigencia AND v.fecha_inicio<=COALESCE(w.fecha_fin,x.fecha_fin) AND w.fecha_inicio<=COALESCE(v.fecha_fin,x.fecha_fin))');
INSERT INTO val_regla VALUES ('OPERACION_PORCENTAJE_SIMULTANEO','OPERACION','trx_beca_vigencia','BLOQUEO','Beneficios simultáneos de la misma inscripción y base no superan 100.','SELECT v.* FROM trx_beca_vigencia v JOIN trx_beca b ON b.id_beca=v.id_beca JOIN trx_inscripcion i ON i.id_inscripcion=b.id_inscripcion JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo WHERE (SELECT SUM(z.porcentaje) FROM trx_beca_vigencia w JOIN trx_beca z ON z.id_beca=w.id_beca WHERE z.id_inscripcion=b.id_inscripcion AND w.fecha_inicio<=v.fecha_inicio AND COALESCE(w.fecha_fin,x.fecha_fin)>=v.fecha_inicio)>100');
INSERT INTO val_regla VALUES ('OPERACION_CONTROL_CICLO','OPERACION','trx_control_carga','BLOQUEO','El curso y período del control pertenecen al mismo ciclo.','SELECT z.* FROM trx_control_carga z JOIN est_curso c ON c.id_curso=z.id_curso JOIN est_periodo_academico p ON p.id_periodo=z.id_periodo WHERE c.id_ciclo<>p.id_ciclo');
INSERT INTO val_regla VALUES ('OPERACION_NACIMIENTO_FUTURO','OPERACION','mae_persona','BLOQUEO','Nacimiento no futuro.','SELECT p.* FROM mae_persona p WHERE p.fecha_nacimiento>CURRENT_DATE');
INSERT INTO val_regla VALUES ('OPERACION_ASISTENCIA_LLEGADA','OPERACION','trx_asistencia','BLOQUEO','Ausencia/justificación sin hora de llegada.','SELECT a.* FROM trx_asistencia a WHERE a.estado IN (''AUSENTE'',''JUSTIFICADA'') AND a.hora_llegada IS NOT NULL');
INSERT INTO val_regla VALUES ('OPERACION_CORTE_EN_CICLO','OPERACION','est_institucion_ciclo','BLOQUEO','Corte de matrícula contenido en su ciclo.','SELECT h.* FROM est_institucion_ciclo h JOIN est_ciclo c ON c.id_ciclo=h.id_ciclo WHERE h.fecha_corte_matricula<c.fecha_inicio OR h.fecha_corte_matricula>c.fecha_fin');
INSERT INTO val_regla VALUES ('OPERACION_CIERRE_INSCRIPCION','OPERACION','trx_inscripcion','BLOQUEO','Inscripción terminada con fecha y motivo.','SELECT i.* FROM trx_inscripcion i WHERE i.estado IN (''FINALIZADA'',''RETIRADA'',''TRASLADADA'') AND (i.fecha_fin IS NULL OR TRIM(i.motivo_fin_inscripcion) IS NULL)');
INSERT INTO val_regla VALUES ('OPERACION_AUDITORIA_TIEMPOS','OPERACION','auditoria_etl_evaluaciones','BLOQUEO','Auditoría con fechas coherentes.','SELECT a.* FROM auditoria_etl_evaluaciones a WHERE (a.estado=''EN_PROCESO'' AND a.fin IS NOT NULL) OR (a.estado IN (''ERROR'',''COMPLETADA'') AND (a.fin IS NULL OR a.fin<a.inicio))');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_TIPO_DOCUMENTO_codigo','OPERACION','cat_tipo_documento','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_tipo_documento s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_TIPO_DOCUMENTO_descripcion','OPERACION','cat_tipo_documento','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_tipo_documento s WHERE TRIM(s.descripcion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_TIPO_INSTITUCION_codigo','OPERACION','cat_tipo_institucion','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_tipo_institucion s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_TIPO_INSTITUCION_descripcion','OPERACION','cat_tipo_institucion','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_tipo_institucion s WHERE TRIM(s.descripcion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_DEPARTAMENTO_codigo','OPERACION','cat_departamento','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_departamento s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_DEPARTAMENTO_nombre','OPERACION','cat_departamento','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_departamento s WHERE TRIM(s.nombre) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_ZONA_nombre','OPERACION','cat_zona','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_zona s WHERE TRIM(s.nombre) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_MODALIDAD_codigo','OPERACION','cat_modalidad','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_modalidad s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_MODALIDAD_descripcion','OPERACION','cat_modalidad','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_modalidad s WHERE TRIM(s.descripcion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_JORNADA_codigo','OPERACION','cat_jornada','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_jornada s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_JORNADA_descripcion','OPERACION','cat_jornada','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_jornada s WHERE TRIM(s.descripcion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_AREA_CONOCIMIENTO_codigo','OPERACION','cat_area_conocimiento','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_area_conocimiento s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_AREA_CONOCIMIENTO_descripcion','OPERACION','cat_area_conocimiento','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_area_conocimiento s WHERE TRIM(s.descripcion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_TIPO_BECA_codigo','OPERACION','cat_tipo_beca','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_tipo_beca s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_TIPO_BECA_descripcion','OPERACION','cat_tipo_beca','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_tipo_beca s WHERE TRIM(s.descripcion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_NIVEL_codigo','OPERACION','cat_nivel','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_nivel s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_NIVEL_nombre','OPERACION','cat_nivel','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_nivel s WHERE TRIM(s.nombre) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_GRADO_codigo','OPERACION','cat_grado','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_grado s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_CAT_GRADO_nombre','OPERACION','cat_grado','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM cat_grado s WHERE TRIM(s.nombre) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_MAE_INSTITUCION_codigo_institucion','OPERACION','mae_institucion','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM mae_institucion s WHERE TRIM(s.codigo_institucion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_MAE_INSTITUCION_nombre','OPERACION','mae_institucion','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM mae_institucion s WHERE TRIM(s.nombre) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_MAE_INSTITUCION_direccion','OPERACION','mae_institucion','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM mae_institucion s WHERE TRIM(s.direccion) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_MAE_PERSONA_primer_nombre','OPERACION','mae_persona','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM mae_persona s WHERE TRIM(s.primer_nombre) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_MAE_PERSONA_primer_apellido','OPERACION','mae_persona','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM mae_persona s WHERE TRIM(s.primer_apellido) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_MAE_ESTUDIANTE_nie','OPERACION','mae_estudiante','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM mae_estudiante s WHERE TRIM(s.nie) IS NULL');
INSERT INTO val_regla VALUES ('OPERACION_TEXTO_MAE_ASIGNATURA_codigo','OPERACION','mae_asignatura','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM mae_asignatura s WHERE TRIM(s.codigo) IS NULL');
