INSERT INTO val_regla VALUES ('OPERACION_CAPACIDAD_ESTRICTA','OPERACION','trx_inscripcion','BLOQUEO','Capacidad simultanea solo cuando se active expresamente la politica.','SELECT i.* FROM trx_inscripcion i JOIN est_curso c ON c.id_curso=i.id_curso JOIN est_ciclo x ON x.id_ciclo=c.id_ciclo CROSS JOIN val_politica v WHERE v.id=1 AND v.capacidad_estricta=1 AND i.estado<>''ANULADA'' AND (SELECT COUNT(*) FROM trx_inscripcion j WHERE j.id_curso=i.id_curso AND j.estado<>''ANULADA'' AND j.fecha_inicio<=i.fecha_inicio AND COALESCE(j.fecha_fin,x.fecha_fin)>=i.fecha_inicio)>c.capacidad_maxima');
