INSERT INTO val_regla VALUES ('STAGING_TRX_CALIFICACION_CK_nota','STAGING','STG_CALIFICACIONES','BLOQUEO','Dominio y rango acordados.','SELECT s.* FROM STG_CALIFICACIONES s WHERE NOT (nota BETWEEN 0 AND 100)');
INSERT INTO val_regla VALUES ('STAGING_TRX_CALIFICACION_NN_fecha_evaluacion','STAGING','STG_CALIFICACIONES','BLOQUEO','Campo obligatorio.','SELECT s.* FROM STG_CALIFICACIONES s WHERE fecha_evaluacion IS NULL');
