INSERT INTO val_regla VALUES ('STAGING_TEXTO_CAT_ZONA_nombre','STAGING','STG_ZONAS','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM STG_ZONAS s WHERE TRIM(s.nombre) IS NULL');
INSERT INTO val_regla VALUES ('STAGING_TEXTO_CAT_AREA_CONOCIMIENTO_codigo','STAGING','STG_AREAS_CONOCIMIENTO','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM STG_AREAS_CONOCIMIENTO s WHERE TRIM(s.codigo) IS NULL');
INSERT INTO val_regla VALUES ('STAGING_TEXTO_CAT_AREA_CONOCIMIENTO_descripcion','STAGING','STG_AREAS_CONOCIMIENTO','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM STG_AREAS_CONOCIMIENTO s WHERE TRIM(s.descripcion) IS NULL');
INSERT INTO val_regla VALUES ('STAGING_TEXTO_MAE_DOCENTE_primer_nombre','STAGING','STG_DOCENTES','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM STG_DOCENTES s WHERE TRIM(s.primer_nombre) IS NULL');
INSERT INTO val_regla VALUES ('STAGING_TEXTO_MAE_DOCENTE_primer_apellido','STAGING','STG_DOCENTES','BLOQUEO','Texto obligatorio significativo.','SELECT s.* FROM STG_DOCENTES s WHERE TRIM(s.primer_apellido) IS NULL');
INSERT INTO val_regla VALUES ('STAGING_PERIODO_CICLO','STAGING','STG_PERIODOS','BLOQUEO','Períodos configurables positivos, contenidos en su ciclo, sin duración fija.','SELECT p.* FROM STG_PERIODOS p JOIN STG_CICLOS c ON c.id_ciclo=p.id_ciclo WHERE (p.numero<1 OR p.numero<>TRUNC(p.numero)) OR p.fecha_inicio<c.fecha_inicio OR p.fecha_fin>c.fecha_fin OR p.fecha_fin<p.fecha_inicio');
INSERT INTO val_regla VALUES ('STAGING_PERIODOS_SOLAPADOS','STAGING','STG_PERIODOS','BLOQUEO','No solapar períodos del mismo ciclo.','SELECT p.* FROM STG_PERIODOS p WHERE EXISTS (SELECT 1 FROM STG_PERIODOS q WHERE q.id_ciclo=p.id_ciclo AND q.id_periodo<>p.id_periodo AND q.fecha_inicio<=p.fecha_fin AND p.fecha_inicio<=q.fecha_fin)');
INSERT INTO val_regla VALUES ('STAGING_PERIODOS_CONSECUTIVOS','STAGING','STG_PERIODOS','AVISO','Períodos numerados 1..N sin huecos y en el orden de sus fechas; un hueco puede indicar un período no cargado.','SELECT p.* FROM STG_PERIODOS p WHERE EXISTS (SELECT 1 FROM STG_PERIODOS q WHERE q.id_ciclo=p.id_ciclo GROUP BY q.id_ciclo HAVING MAX(q.numero)<>COUNT(*)) OR EXISTS (SELECT 1 FROM STG_PERIODOS q WHERE q.id_ciclo=p.id_ciclo AND q.id_periodo<>p.id_periodo AND ((q.numero<p.numero AND q.fecha_inicio>p.fecha_inicio) OR (q.numero>p.numero AND q.fecha_inicio<p.fecha_inicio)))');
INSERT INTO val_regla VALUES ('STAGING_CICLO_ANIO_INICIO','STAGING','STG_CICLOS','AVISO','El año de referencia es el año de inicio del ciclo, aunque cruce años calendario.','SELECT c.* FROM STG_CICLOS c WHERE c.anio<>EXTRACT(YEAR FROM c.fecha_inicio)');
INSERT INTO val_regla VALUES ('STAGING_PLAN_CICLO','STAGING','STG_PONDERACIONES','BLOQUEO','Curso y período deben pertenecer al mismo ciclo.','SELECT p.* FROM STG_PONDERACIONES p JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=p.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=a.id_curso JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo WHERE c.id_ciclo<>x.id_ciclo');
INSERT INTO val_regla VALUES ('STAGING_PLAN_COMPLETO','STAGING','STG_PONDERACIONES','BLOQUEO','Un plan publicado cubre todos los períodos configurados de su ciclo.','SELECT p.* FROM STG_PONDERACIONES p WHERE p.id_ponderacion_periodo IN (SELECT q.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_curso_asignatura,COUNT(*) OVER (PARTITION BY w.id_curso_asignatura) AS publicados FROM STG_PONDERACIONES w WHERE w.estado=''PUBLICADO'') q LEFT JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=q.id_curso_asignatura LEFT JOIN STG_CURSOS c ON c.id_curso=a.id_curso LEFT JOIN (SELECT id_ciclo,COUNT(*) AS periodos FROM STG_PERIODOS GROUP BY id_ciclo) v ON v.id_ciclo=c.id_ciclo WHERE q.publicados<>COALESCE(v.periodos,0))');
INSERT INTO val_regla VALUES ('STAGING_OFERTA_CON_PLAN','STAGING','STG_CURSOS_ASIGNATURAS','PENDIENTE','Una oferta activa con matrícula no puede ocultar un plan anual ausente.','SELECT o.* FROM STG_CURSOS_ASIGNATURAS o LEFT JOIN (SELECT id_curso_asignatura,COUNT(*) AS publicados FROM STG_PONDERACIONES WHERE estado=''PUBLICADO'' GROUP BY id_curso_asignatura) w ON w.id_curso_asignatura=o.id_curso_asignatura LEFT JOIN STG_CURSOS c ON c.id_curso=o.id_curso LEFT JOIN (SELECT id_ciclo,COUNT(*) AS periodos FROM STG_PERIODOS GROUP BY id_ciclo) v ON v.id_ciclo=c.id_ciclo WHERE o.estado=''ACTIVA'' AND EXISTS (SELECT 1 FROM STG_INSCRIPCIONES i WHERE i.id_curso=o.id_curso AND i.estado<>''ANULADA'') AND COALESCE(w.publicados,0)<>COALESCE(v.periodos,0)');
INSERT INTO val_regla VALUES ('STAGING_PLAN_CON_PLAZO','STAGING','STG_PONDERACIONES','PENDIENTE','Todo componente publicado tiene plazo ordinario del contexto correspondiente.','SELECT p.* FROM STG_PONDERACIONES p JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=o.id_curso WHERE p.estado=''PUBLICADO'' AND NOT EXISTS (SELECT 1 FROM STG_PLAZOS_NOTAS w WHERE w.id_institucion=c.id_institucion AND w.id_ciclo=c.id_ciclo AND w.id_grado=c.id_grado AND w.id_periodo=p.id_periodo AND w.tipo_intento=''ORDINARIA'')');
INSERT INTO val_regla VALUES ('STAGING_PESOS_COMPARABLES','STAGING','STG_PONDERACIONES','BLOQUEO','Mismo ciclo, grado y asignatura: igual vector normalizado.','SELECT p.* FROM STG_PONDERACIONES p WHERE p.id_ponderacion_periodo IN (SELECT x.id_ponderacion_periodo FROM (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM STG_PONDERACIONES w JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=a.id_curso WHERE w.estado=''PUBLICADO'') x JOIN (SELECT w.id_ponderacion_periodo,w.id_periodo,w.peso,SUM(w.peso) OVER (PARTITION BY w.id_curso_asignatura) AS total,c.id_ciclo,c.id_grado,a.id_asignatura FROM STG_PONDERACIONES w JOIN STG_CURSOS_ASIGNATURAS a ON a.id_curso_asignatura=w.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=a.id_curso WHERE w.estado=''PUBLICADO'') y ON y.id_periodo=x.id_periodo AND y.id_ciclo=x.id_ciclo AND y.id_grado=x.id_grado AND y.id_asignatura=x.id_asignatura WHERE ABS(x.peso*y.total-y.peso*x.total)>0.00000001)');
INSERT INTO val_regla VALUES ('STAGING_INSCRIPCION_CICLO','STAGING','STG_INSCRIPCIONES','BLOQUEO','Pertenencia dentro del ciclo, con intervalos inclusivos.','SELECT i.* FROM STG_INSCRIPCIONES i JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE i.fecha_inicio<x.fecha_inicio OR i.fecha_inicio>x.fecha_fin OR (i.fecha_fin IS NOT NULL AND (i.fecha_fin<i.fecha_inicio OR i.fecha_fin>x.fecha_fin))');
INSERT INTO val_regla VALUES ('STAGING_INSCRIPCIONES_SOLAPADAS','STAGING','STG_INSCRIPCIONES','BLOQUEO','No solapar matrículas ordinarias del mismo estudiante y ciclo.','SELECT i.* FROM STG_INSCRIPCIONES i WHERE i.id_inscripcion IN (SELECT w.id_inscripcion FROM (SELECT v.*,LAG(v.max_fin) OVER (PARTITION BY v.id_estudiante,v.id_ciclo ORDER BY v.fecha_inicio,v.id_inscripcion) AS fin_previo FROM (SELECT t.id_inscripcion,t.id_estudiante,c.id_ciclo,t.fecha_inicio,COALESCE(t.fecha_fin,x.fecha_fin) AS fin,MAX(COALESCE(t.fecha_fin,x.fecha_fin)) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion ROWS UNBOUNDED PRECEDING) AS max_fin,LEAD(t.fecha_inicio) OVER (PARTITION BY t.id_estudiante,c.id_ciclo ORDER BY t.fecha_inicio,t.id_inscripcion) AS inicio_siguiente FROM STG_INSCRIPCIONES t JOIN STG_CURSOS c ON c.id_curso=t.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE t.estado<>''ANULADA'') v) w WHERE w.fin_previo>=w.fecha_inicio OR w.inicio_siguiente<=w.fin)');
INSERT INTO val_regla VALUES ('STAGING_ASIGNACION_CICLO','STAGING','STG_ASIGNACIONES_DOCENTES','BLOQUEO','La responsabilidad ordinaria pertenece al ciclo de la oferta.','SELECT a.* FROM STG_ASIGNACIONES_DOCENTES a JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=o.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE a.fecha_inicio<x.fecha_inicio OR a.fecha_inicio>x.fecha_fin OR (a.fecha_fin IS NOT NULL AND (a.fecha_fin<a.fecha_inicio OR a.fecha_fin>x.fecha_fin))');
INSERT INTO val_regla VALUES ('STAGING_ASIGNACIONES_SOLAPADAS','STAGING','STG_ASIGNACIONES_DOCENTES','BLOQUEO','Un responsable por oferta y fecha.','SELECT a.* FROM STG_ASIGNACIONES_DOCENTES a JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=a.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=o.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE a.estado<>''ANULADA'' AND EXISTS (SELECT 1 FROM STG_ASIGNACIONES_DOCENTES b WHERE b.id_asignacion<>a.id_asignacion AND b.id_curso_asignatura=a.id_curso_asignatura AND b.estado<>''ANULADA'' AND a.fecha_inicio<=COALESCE(b.fecha_fin,x.fecha_fin) AND b.fecha_inicio<=COALESCE(a.fecha_fin,x.fecha_fin))');
INSERT INTO val_regla VALUES ('STAGING_PLAZO_CICLO','STAGING','STG_PLAZOS_NOTAS','BLOQUEO','El período del plazo pertenece a su ciclo.','SELECT w.* FROM STG_PLAZOS_NOTAS w JOIN STG_PERIODOS p ON p.id_periodo=w.id_periodo WHERE w.id_ciclo<>p.id_ciclo');
INSERT INTO val_regla VALUES ('STAGING_RECUPERACION_FECHAS','STAGING','STG_PLAZOS_NOTAS','BLOQUEO','Recuperación exige intervalo ordenado; ordinaria lo deja vacío.','SELECT w.* FROM STG_PLAZOS_NOTAS w WHERE (w.tipo_intento=''ORDINARIA'' AND (w.fecha_inicio_recuperacion IS NOT NULL OR w.fecha_fin_recuperacion IS NOT NULL)) OR (w.tipo_intento=''RECUPERACION'' AND (w.fecha_inicio_recuperacion IS NULL OR w.fecha_fin_recuperacion IS NULL OR w.fecha_fin_recuperacion<w.fecha_inicio_recuperacion))');
INSERT INTO val_regla VALUES ('STAGING_CALIFICACION_CONTEXTO','STAGING','STG_CALIFICACIONES','BLOQUEO','Calificación, inscripción y asignación corresponden a la misma oferta publicada.','SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=n.id_asignacion_docente WHERE i.id_curso<>o.id_curso OR a.id_curso_asignatura<>o.id_curso_asignatura OR i.estado=''ANULADA'' OR a.estado=''ANULADA'' OR p.estado<>''PUBLICADO''');
INSERT INTO val_regla VALUES ('STAGING_TIPO_RESULTADO','STAGING','STG_CALIFICACIONES','BLOQUEO','Resultado numérico o cualitativo coherente con la oferta.','SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE (o.tipo_resultado=''NUMERICA'' AND (n.nota IS NULL OR n.resultado_cualitativo IS NOT NULL)) OR (o.tipo_resultado=''CUALITATIVA'' AND (n.nota IS NOT NULL OR n.resultado_cualitativo IS NULL))');
INSERT INTO val_regla VALUES ('STAGING_ORDINARIA_VIGENCIA','STAGING','STG_CALIFICACIONES','BLOQUEO','La fecha académica ordinaria está en período, matrícula y responsabilidad.','SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento=''ORDINARIA'' AND (n.fecha_evaluacion<x.fecha_inicio OR n.fecha_evaluacion>x.fecha_fin OR n.fecha_evaluacion<i.fecha_inicio OR n.fecha_evaluacion>COALESCE(i.fecha_fin,x.fecha_fin) OR n.fecha_evaluacion<a.fecha_inicio OR n.fecha_evaluacion>COALESCE(a.fecha_fin,x.fecha_fin))');
INSERT INTO val_regla VALUES ('STAGING_RECUPERACION_RESPONSABLE','STAGING','STG_CALIFICACIONES','BLOQUEO','La recuperación queda a cargo de una asignación vigente en algún momento del período que recupera.','SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=n.id_asignacion_docente WHERE n.tipo_intento=''RECUPERACION'' AND (a.fecha_inicio>x.fecha_fin OR COALESCE(a.fecha_fin,x.fecha_fin)<x.fecha_inicio)');
INSERT INTO val_regla VALUES ('STAGING_ORIGEN_RECUPERACION','STAGING','STG_CALIFICACIONES','BLOQUEO','La recuperación referencia su ordinaria y conserva inscripción y plan.','SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_CALIFICACIONES b ON b.id_calificacion=n.id_calificacion_ordinaria WHERE n.tipo_intento=''RECUPERACION'' AND (b.tipo_intento<>''ORDINARIA'' OR b.numero_intento<>1 OR b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.fecha_evaluacion>n.fecha_evaluacion)');
INSERT INTO val_regla VALUES ('STAGING_VERSION_ANTERIOR','STAGING','STG_CALIFICACIONES','BLOQUEO','La sustituida es la versión previa del mismo intento y contexto.','SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_CALIFICACIONES b ON b.id_calificacion=n.id_calificacion_sustituida WHERE b.id_inscripcion<>n.id_inscripcion OR b.id_ponderacion_periodo<>n.id_ponderacion_periodo OR b.tipo_intento<>n.tipo_intento OR b.numero_intento<>n.numero_intento OR b.version+1<>n.version OR b.fecha_registro>n.fecha_registro');
INSERT INTO val_regla VALUES ('STAGING_CAPTURA_AUTORIZADA','STAGING','STG_CALIFICACIONES','BLOQUEO','Existe plazo compatible y la captura no precede apertura ni supera cierre real.','SELECT n.* FROM STG_CALIFICACIONES n JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE n.id_calificacion NOT IN (SELECT m.id_calificacion FROM STG_CALIFICACIONES m JOIN STG_INSCRIPCIONES j ON j.id_inscripcion=m.id_inscripcion JOIN STG_CURSOS d ON d.id_curso=j.id_curso JOIN STG_PONDERACIONES q ON q.id_ponderacion_periodo=m.id_ponderacion_periodo JOIN STG_PLAZOS_NOTAS w ON w.id_institucion=d.id_institucion AND w.id_ciclo=d.id_ciclo AND w.id_grado=d.id_grado AND w.id_periodo=q.id_periodo AND w.tipo_intento=m.tipo_intento WHERE m.fecha_registro>=w.fecha_apertura_registro AND (w.fecha_cierre_registro IS NULL OR m.fecha_registro<=w.fecha_cierre_registro) AND (m.tipo_intento=''ORDINARIA'' OR m.fecha_evaluacion BETWEEN w.fecha_inicio_recuperacion AND w.fecha_fin_recuperacion))');
INSERT INTO val_regla VALUES ('STAGING_REGISTRO_NO_ANTICIPADO','STAGING','STG_CALIFICACIONES','BLOQUEO','El registro no precede al hecho académico.','SELECT n.* FROM STG_CALIFICACIONES n WHERE TRUNC(n.fecha_registro)<n.fecha_evaluacion');
INSERT INTO val_regla VALUES ('STAGING_RESULTADO_CORRESPONDE','STAGING','STG_RESULTADOS_PERIODO','BLOQUEO','La referencia seleccionada corresponde a estudiante, materia y período.','SELECT r.* FROM STG_RESULTADOS_PERIODO r JOIN STG_CALIFICACIONES n ON n.id_calificacion=r.id_calificacion_seleccionada JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=n.id_inscripcion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura WHERE r.id_estudiante<>i.id_estudiante OR r.id_asignatura<>o.id_asignatura OR r.id_periodo<>p.id_periodo OR n.fecha_validacion IS NULL OR r.fecha_seleccion<n.fecha_validacion OR (r.fecha_cierre IS NOT NULL AND r.fecha_cierre<r.fecha_seleccion) OR (n.fecha_anulacion IS NOT NULL AND n.fecha_anulacion<=r.fecha_seleccion)');
INSERT INTO val_regla VALUES ('STAGING_SELECCION_VERSION_VIGENTE','STAGING','STG_RESULTADOS_PERIODO','BLOQUEO','Una selección usa la última versión validada de su intento en ese momento.','SELECT r.* FROM STG_RESULTADOS_PERIODO r JOIN STG_CALIFICACIONES n ON n.id_calificacion=r.id_calificacion_seleccionada WHERE EXISTS (SELECT 1 FROM STG_CALIFICACIONES v WHERE v.id_inscripcion=n.id_inscripcion AND v.id_ponderacion_periodo=n.id_ponderacion_periodo AND v.tipo_intento=n.tipo_intento AND v.numero_intento=n.numero_intento AND v.version>n.version AND v.fecha_validacion<=r.fecha_seleccion)');
INSERT INTO val_regla VALUES ('STAGING_SELECCION_POLITICA','STAGING','STG_RESULTADOS_PERIODO','BLOQUEO','La elección respeta mejor nota o última recuperación a fecha de selección, sin anticipar eventos futuros.','SELECT r.* FROM STG_RESULTADOS_PERIODO r WHERE r.id_resultado IN (SELECT x.id_resultado FROM STG_RESULTADOS_PERIODO x JOIN STG_CALIFICACIONES n ON n.id_calificacion=x.id_calificacion_seleccionada JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=n.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN STG_CALIFICACIONES m ON m.id_inscripcion=n.id_inscripcion AND m.id_ponderacion_periodo=n.id_ponderacion_periodo WHERE m.fecha_validacion<=x.fecha_seleccion AND (m.fecha_anulacion IS NULL OR m.fecha_anulacion>x.fecha_seleccion) AND ((o.regla_recuperacion=''MEJOR_NOTA'' AND o.tipo_resultado=''NUMERICA'' AND m.nota>n.nota) OR (o.regla_recuperacion=''ULTIMA_RECUPERACION'' AND m.numero_intento>n.numero_intento)) AND NOT EXISTS (SELECT 1 FROM STG_CALIFICACIONES v WHERE v.id_inscripcion=m.id_inscripcion AND v.id_ponderacion_periodo=m.id_ponderacion_periodo AND v.tipo_intento=m.tipo_intento AND v.numero_intento=m.numero_intento AND v.version>m.version AND v.fecha_validacion<=x.fecha_seleccion))');
INSERT INTO val_regla VALUES ('STAGING_SESION_CONTEXTO','STAGING','STG_SESIONES','BLOQUEO','Sesión y responsabilidad compatibles; noche puede terminar al día siguiente.','SELECT s.* FROM STG_SESIONES s JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN STG_PERIODOS x ON x.id_periodo=p.id_periodo JOIN STG_ASIGNACIONES_DOCENTES a ON a.id_asignacion=s.id_asignacion WHERE p.id_curso_asignatura<>a.id_curso_asignatura OR s.fecha_academica<x.fecha_inicio OR s.fecha_academica>x.fecha_fin OR s.fecha_academica<a.fecha_inicio OR s.fecha_academica>COALESCE(a.fecha_fin,x.fecha_fin) OR s.fin<=s.inicio OR TRUNC(s.inicio)<>s.fecha_academica OR a.estado=''ANULADA''');
INSERT INTO val_regla VALUES ('STAGING_SESIONES_SIMULTANEAS','STAGING','STG_SESIONES','BLOQUEO','Un docente o grupo no recibe dos sesiones simultáneas.','SELECT s.* FROM STG_SESIONES s WHERE s.id_sesion IN (SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,b.id_docente AS k,MAX(t.fin) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY b.id_docente ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM STG_SESIONES t JOIN STG_ASIGNACIONES_DOCENTES b ON b.id_asignacion=t.id_asignacion WHERE t.estado<>''CANCELADA'') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin UNION SELECT id_sesion FROM (SELECT v.*,LAG(v.max_hasta) OVER (PARTITION BY v.k ORDER BY v.inicio,v.id_sesion) AS fin_previo FROM (SELECT t.id_sesion,t.inicio,t.fin,z.id_curso AS k,MAX(t.fin) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion ROWS UNBOUNDED PRECEDING) AS max_hasta,LEAD(t.inicio) OVER (PARTITION BY z.id_curso ORDER BY t.inicio,t.id_sesion) AS inicio_siguiente FROM STG_SESIONES t JOIN STG_PONDERACIONES q ON q.id_ponderacion_periodo=t.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS z ON z.id_curso_asignatura=q.id_curso_asignatura WHERE t.estado<>''CANCELADA'') v) w WHERE w.fin_previo>w.inicio OR w.inicio_siguiente<w.fin)');
INSERT INTO val_regla VALUES ('STAGING_ASISTENCIA_CONTEXTO','STAGING','STG_ASISTENCIAS','BLOQUEO','La asistencia pertenece al curso e intervalo de la sesión.','SELECT a.* FROM STG_ASISTENCIAS a JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=a.id_inscripcion JOIN STG_SESIONES s ON s.id_sesion=a.id_sesion JOIN STG_PONDERACIONES p ON p.id_ponderacion_periodo=s.id_ponderacion_periodo JOIN STG_CURSOS_ASIGNATURAS o ON o.id_curso_asignatura=p.id_curso_asignatura JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE i.id_curso<>o.id_curso OR i.estado=''ANULADA'' OR s.estado<>''IMPARTIDA'' OR s.fecha_academica<i.fecha_inicio OR s.fecha_academica>COALESCE(i.fecha_fin,x.fecha_fin) OR a.fecha_registro<s.fin OR (a.estado IN (''AUSENTE'',''JUSTIFICADA'') AND a.hora_llegada IS NOT NULL)');
INSERT INTO val_regla VALUES ('STAGING_BECA_HABILITADA','STAGING','STG_BECAS','BLOQUEO','El beneficio respeta la habilitación histórica del centro.','SELECT b.* FROM STG_BECAS b JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_INSTITUCIONES_CICLO h ON h.id_institucion=c.id_institucion AND h.id_ciclo=c.id_ciclo WHERE h.permite_becas<>1 OR i.estado=''ANULADA''');
INSERT INTO val_regla VALUES ('STAGING_BECA_VIGENCIA','STAGING','STG_BECAS_VIGENCIA','BLOQUEO','El intervalo efectivo queda dentro de matrícula y ciclo.','SELECT v.* FROM STG_BECAS_VIGENCIA v JOIN STG_BECAS b ON b.id_beca=v.id_beca JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE v.fecha_inicio<i.fecha_inicio OR v.fecha_inicio>COALESCE(i.fecha_fin,x.fecha_fin) OR (v.fecha_fin IS NOT NULL AND (v.fecha_fin<v.fecha_inicio OR v.fecha_fin>COALESCE(i.fecha_fin,x.fecha_fin))) OR (v.fecha_fin IS NULL AND v.motivo_fin IS NOT NULL) OR (v.fecha_fin IS NOT NULL AND v.motivo_fin IS NULL)');
INSERT INTO val_regla VALUES ('STAGING_BECA_SOLAPADA','STAGING','STG_BECAS_VIGENCIA','BLOQUEO','Una beca no tiene intervalos efectivos solapados.','SELECT v.* FROM STG_BECAS_VIGENCIA v JOIN STG_BECAS b ON b.id_beca=v.id_beca JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE EXISTS (SELECT 1 FROM STG_BECAS_VIGENCIA w WHERE w.id_beca=v.id_beca AND w.id_vigencia<>v.id_vigencia AND v.fecha_inicio<=COALESCE(w.fecha_fin,x.fecha_fin) AND w.fecha_inicio<=COALESCE(v.fecha_fin,x.fecha_fin))');
INSERT INTO val_regla VALUES ('STAGING_PORCENTAJE_SIMULTANEO','STAGING','STG_BECAS_VIGENCIA','BLOQUEO','Beneficios simultáneos de la misma inscripción y base no superan 100.','SELECT v.* FROM STG_BECAS_VIGENCIA v JOIN STG_BECAS b ON b.id_beca=v.id_beca JOIN STG_INSCRIPCIONES i ON i.id_inscripcion=b.id_inscripcion JOIN STG_CURSOS c ON c.id_curso=i.id_curso JOIN STG_CICLOS x ON x.id_ciclo=c.id_ciclo WHERE (SELECT SUM(z.porcentaje) FROM STG_BECAS_VIGENCIA w JOIN STG_BECAS z ON z.id_beca=w.id_beca WHERE z.id_inscripcion=b.id_inscripcion AND w.fecha_inicio<=v.fecha_inicio AND COALESCE(w.fecha_fin,x.fecha_fin)>=v.fecha_inicio)>100');
INSERT INTO val_regla VALUES ('STAGING_CONTROL_CICLO','STAGING','STG_CONTROL_CARGA','BLOQUEO','El curso y período del control pertenecen al mismo ciclo.','SELECT z.* FROM STG_CONTROL_CARGA z JOIN STG_CURSOS c ON c.id_curso=z.id_curso JOIN STG_PERIODOS p ON p.id_periodo=z.id_periodo WHERE c.id_ciclo<>p.id_ciclo');
INSERT INTO val_regla VALUES ('STAGING_ASISTENCIA_LLEGADA','STAGING','STG_ASISTENCIAS','BLOQUEO','Ausencia/justificación sin hora de llegada.','SELECT a.* FROM STG_ASISTENCIAS a WHERE a.estado IN (''AUSENTE'',''JUSTIFICADA'') AND a.hora_llegada IS NOT NULL');
INSERT INTO val_regla VALUES ('STAGING_CORTE_EN_CICLO','STAGING','STG_INSTITUCIONES_CICLO','BLOQUEO','Corte de matrícula contenido en su ciclo.','SELECT h.* FROM STG_INSTITUCIONES_CICLO h JOIN STG_CICLOS c ON c.id_ciclo=h.id_ciclo WHERE h.fecha_corte_matricula<c.fecha_inicio OR h.fecha_corte_matricula>c.fecha_fin');
INSERT INTO val_regla VALUES ('STAGING_CIERRE_INSCRIPCION','STAGING','STG_INSCRIPCIONES','BLOQUEO','Inscripción terminada con fecha y motivo.','SELECT i.* FROM STG_INSCRIPCIONES i WHERE i.estado IN (''FINALIZADA'',''RETIRADA'',''TRASLADADA'') AND (i.fecha_fin IS NULL OR TRIM(i.motivo_fin_inscripcion) IS NULL)');
